@python_2_unicode_compatible
class Literal(JSONLogic):

    def __str__(self):
        return u"<LITERAL>"

@python_2_unicode_compatible
class StringLiteral(Literal):

    def __init__(self, s=None, json_dict=None):
        if json_dict:
            self.s = json_dict['s']
        else:
            self.s = s

    def __eq__(self, b):
        return isinstance(b, StringLiteral) and self.s == b.s

    def __lt__(self, b):
        assert isinstance(b, StringLiteral)
        return self.s < b.s

    def __le__(self, b):
        assert isinstance(b, StringLiteral)
        return self.s <= b.s

    def __ne__(self, b):
        return not isinstance(b, StringLiteral) or self.s != b.s

    def __ge__(self, b):
        assert isinstance(b, StringLiteral)
        return self.s >= b.s

    def __gt__(self, b):
        assert isinstance(b, StringLiteral)
        return self.s > b.s

    def get_literal(self):
        return self.s

    def __str__(self):
        return u'"' + text_type(self.s.replace('"', '\\"')) + u'"'

    def __repr__(self):
        return u'StringLiteral(' + repr(self.s) + ')'

    def to_dict(self):
        return {'pt': 'StringLiteral', 's': self.s}

    def __hash__(self):
        return hash(self.s)

