def surfenergy(prot, surf, numbeads, numint, param):
    ep = float(param[0])
    sig = float(param[1])
    scale = param[2]
    energy = numpy.array([0.,0.])
    for i in xrange(numint):
        r2 = surf[i/numbeads,:] - prot[i%numbeads,:]
        r2 = numpy.sum(r2**2)
        ne = sig*sig/r2
        ne6 = ne*ne*ne
        ne12 = ne6*ne6
        energy[0] += ep*ne12
        energy[1] += scale[i]*ep*(12*ne12 - 18*ne6*ne*ne + 4*ne6)
    return energy

